BEGIN;
CREATE SCHEMA exam;
REVOKE ALL ON SCHEMA exam FROM PUBLIC;
CREATE TABLE exam.users(id uuid PRIMARY KEY, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','deleted')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exam.user_profiles(user_id uuid PRIMARY KEY REFERENCES exam.users, display_name text NOT NULL DEFAULT '', preferred_language text NOT NULL DEFAULT 'en', timezone text NOT NULL DEFAULT 'Asia/Kolkata');
CREATE TABLE exam.roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE);
CREATE TABLE exam.permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE);
CREATE TABLE exam.role_permissions(role_id uuid REFERENCES exam.roles, permission_id uuid REFERENCES exam.permissions, PRIMARY KEY(role_id,permission_id));
CREATE TABLE exam.user_roles(user_id uuid REFERENCES exam.users, role_id uuid REFERENCES exam.roles, granted_by uuid REFERENCES exam.users, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,role_id));
CREATE TABLE exam.media_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), storage_key text NOT NULL UNIQUE, mime_type text NOT NULL, checksum text NOT NULL, rights_status text NOT NULL DEFAULT 'unreviewed');
CREATE TABLE exam.sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_type text NOT NULL, publisher text NOT NULL, url text, asset_id uuid REFERENCES exam.media_assets, checksum text, retrieved_at timestamptz, rights_notes text);
CREATE TABLE exam.exam_families(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL);
CREATE TABLE exam.exams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), family_id uuid NOT NULL REFERENCES exam.exam_families, slug text NOT NULL UNIQUE, name text NOT NULL, conducting_body text, status text NOT NULL DEFAULT 'draft');
CREATE TABLE exam.exam_stages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_id uuid NOT NULL REFERENCES exam.exams, code text NOT NULL, name text NOT NULL, assessment_type text NOT NULL DEFAULT 'objective', display_order integer NOT NULL DEFAULT 0, UNIQUE(exam_id,code));
CREATE TABLE exam.syllabus_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_stage_id uuid NOT NULL REFERENCES exam.exam_stages, version integer NOT NULL CHECK(version>0), source_id uuid REFERENCES exam.sources, effective_from date, status text NOT NULL DEFAULT 'draft', UNIQUE(exam_stage_id,version));
CREATE TABLE exam.subjects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL);
CREATE TABLE exam.exam_subjects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), syllabus_version_id uuid NOT NULL REFERENCES exam.syllabus_versions, subject_id uuid NOT NULL REFERENCES exam.subjects, display_order integer NOT NULL DEFAULT 0, UNIQUE(syllabus_version_id,subject_id));
CREATE TABLE exam.topics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_subject_id uuid NOT NULL REFERENCES exam.exam_subjects, parent_topic_id uuid, code text NOT NULL, name text NOT NULL, UNIQUE(id,exam_subject_id), UNIQUE(exam_subject_id,code), FOREIGN KEY(parent_topic_id,exam_subject_id) REFERENCES exam.topics(id,exam_subject_id), CHECK(parent_topic_id IS DISTINCT FROM id));
CREATE TABLE exam.user_exam_preferences(user_id uuid REFERENCES exam.users, exam_id uuid REFERENCES exam.exams, target_date date, PRIMARY KEY(user_id,exam_id));
CREATE TABLE exam.questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), origin_type text NOT NULL CHECK(origin_type IN ('original','generated','historical')), derived_from_question_id uuid REFERENCES exam.questions, created_by uuid REFERENCES exam.users, status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exam.question_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_id uuid NOT NULL REFERENCES exam.questions, version integer NOT NULL CHECK(version>0), question_type text NOT NULL DEFAULT 'single_choice' CHECK(question_type IN ('single_choice','multiple_choice','numeric')), difficulty text NOT NULL CHECK(difficulty IN ('easy','medium','hard')), content_hash text NOT NULL, review_status text NOT NULL DEFAULT 'draft' CHECK(review_status IN ('draft','review','published','retired')), published_at timestamptz, UNIQUE(question_id,version));
CREATE TABLE exam.question_translations(question_version_id uuid REFERENCES exam.question_versions, language text, stem text NOT NULL, explanation text NOT NULL, review_status text NOT NULL DEFAULT 'draft', PRIMARY KEY(question_version_id,language));
CREATE TABLE exam.question_options(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_version_id uuid NOT NULL REFERENCES exam.question_versions, option_key text NOT NULL, display_order integer NOT NULL, UNIQUE(question_version_id,option_key));
CREATE TABLE exam.question_option_translations(option_id uuid REFERENCES exam.question_options, language text, content text NOT NULL, PRIMARY KEY(option_id,language));
CREATE TABLE exam.question_answer_keys(question_version_id uuid PRIMARY KEY REFERENCES exam.question_versions, answer_specification jsonb NOT NULL, grading_method text NOT NULL, explanation_evidence text);
CREATE TABLE exam.question_topic_mappings(question_version_id uuid REFERENCES exam.question_versions, topic_id uuid REFERENCES exam.topics, is_primary boolean NOT NULL DEFAULT false, PRIMARY KEY(question_version_id,topic_id));
CREATE TABLE exam.question_groups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version integer NOT NULL DEFAULT 1, group_type text NOT NULL, content_by_language jsonb NOT NULL);
CREATE TABLE exam.question_group_members(group_id uuid REFERENCES exam.question_groups, question_version_id uuid REFERENCES exam.question_versions, position integer NOT NULL, PRIMARY KEY(group_id,question_version_id), UNIQUE(group_id,position));
CREATE TABLE exam.question_assets(question_version_id uuid REFERENCES exam.question_versions, asset_id uuid REFERENCES exam.media_assets, usage text NOT NULL, PRIMARY KEY(question_version_id,asset_id));
CREATE TABLE exam.exam_papers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_stage_id uuid NOT NULL REFERENCES exam.exam_stages, exam_year integer NOT NULL, exam_date date, shift text, paper_code text, paper_source_id uuid NOT NULL REFERENCES exam.sources, key_source_id uuid REFERENCES exam.sources, key_status text NOT NULL CHECK(key_status IN ('unavailable','provisional','final_verified')));
CREATE TABLE exam.question_paper_occurrences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_version_id uuid NOT NULL REFERENCES exam.question_versions, paper_id uuid NOT NULL REFERENCES exam.exam_papers, question_number text NOT NULL, paper_locator text NOT NULL, key_locator text, evidence_status text NOT NULL CHECK(evidence_status IN ('unverified','paper_verified','verified_pyq')), UNIQUE(paper_id,question_number), CHECK(evidence_status<>'verified_pyq' OR key_locator IS NOT NULL));
CREATE TABLE exam.question_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), question_version_id uuid NOT NULL REFERENCES exam.question_versions, occurrence_id uuid REFERENCES exam.question_paper_occurrences, reviewer_id uuid NOT NULL REFERENCES exam.users, review_type text NOT NULL, decision text NOT NULL, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exam.question_import_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid REFERENCES exam.sources, submitted_by uuid REFERENCES exam.users, status text NOT NULL DEFAULT 'staged', validation_summary jsonb NOT NULL DEFAULT '{}');
CREATE TABLE exam.question_import_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES exam.question_import_batches, row_number integer NOT NULL, candidate_payload jsonb NOT NULL, validation_errors jsonb NOT NULL DEFAULT '[]', question_id uuid REFERENCES exam.questions, UNIQUE(batch_id,row_number));
CREATE TABLE exam.mock_tests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), exam_stage_id uuid NOT NULL REFERENCES exam.exam_stages, title text NOT NULL, test_mode text NOT NULL CHECK(test_mode IN ('full_length','subject','topic','pyq','difficulty','mixed','weak_topic')), created_by uuid REFERENCES exam.users, status text NOT NULL DEFAULT 'draft');
CREATE TABLE exam.test_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), mock_test_id uuid NOT NULL REFERENCES exam.mock_tests, version integer NOT NULL CHECK(version>0), syllabus_version_id uuid NOT NULL REFERENCES exam.syllabus_versions, assembly_mode text NOT NULL DEFAULT 'fixed' CHECK(assembly_mode IN ('fixed','blueprint')), duration_seconds integer NOT NULL CHECK(duration_seconds>0), rules jsonb NOT NULL DEFAULT '{}', published_at timestamptz, UNIQUE(mock_test_id,version));
CREATE TABLE exam.test_sections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), test_version_id uuid NOT NULL REFERENCES exam.test_versions, name text NOT NULL, position integer NOT NULL, question_count integer NOT NULL CHECK(question_count>0), time_limit_seconds integer CHECK(time_limit_seconds>0), scoring_rule jsonb NOT NULL, navigation_rule jsonb NOT NULL DEFAULT '{}', UNIQUE(test_version_id,position), UNIQUE(id,test_version_id));
CREATE TABLE exam.test_questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), test_section_id uuid NOT NULL REFERENCES exam.test_sections, question_version_id uuid NOT NULL REFERENCES exam.question_versions, position integer NOT NULL, scoring_override jsonb, UNIQUE(test_section_id,position), UNIQUE(test_section_id,question_version_id));
CREATE TABLE exam.test_blueprint_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), test_section_id uuid NOT NULL REFERENCES exam.test_sections, topic_id uuid REFERENCES exam.topics, difficulty text, source_category text, required_count integer NOT NULL CHECK(required_count>0), selection_priority integer NOT NULL DEFAULT 0);
CREATE TABLE exam.user_free_allowances(user_id uuid PRIMARY KEY REFERENCES exam.users, granted_count integer NOT NULL DEFAULT 2 CHECK(granted_count=2), used_count integer NOT NULL DEFAULT 0 CHECK(used_count BETWEEN 0 AND 2), policy_version text NOT NULL DEFAULT 'approved-2026-10-04');
CREATE TABLE exam.subscription_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, status text NOT NULL DEFAULT 'draft');
CREATE TABLE exam.subscription_plan_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES exam.subscription_plans, version integer NOT NULL, price_minor bigint NOT NULL CHECK(price_minor>0), currency text NOT NULL CHECK(currency='INR'), duration_days integer NOT NULL DEFAULT 30 CHECK(duration_days=30), billing_mode text NOT NULL DEFAULT 'prepaid' CHECK(billing_mode='prepaid'), all_exams boolean NOT NULL DEFAULT true, UNIQUE(plan_id,version));
CREATE TABLE exam.plan_exam_access(plan_version_id uuid REFERENCES exam.subscription_plan_versions, exam_id uuid REFERENCES exam.exams, PRIMARY KEY(plan_version_id,exam_id));
CREATE TABLE exam.payment_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES exam.users, plan_version_id uuid NOT NULL REFERENCES exam.subscription_plan_versions, provider_order_id text NOT NULL UNIQUE, amount_minor bigint NOT NULL CHECK(amount_minor>0), currency text NOT NULL CHECK(currency='INR'), status text NOT NULL DEFAULT 'created' CHECK(status IN ('created','paid','cancelled')), idempotency_key uuid NOT NULL, UNIQUE(user_id,idempotency_key));
CREATE TABLE exam.payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES exam.payment_orders, provider_payment_id text NOT NULL UNIQUE, amount_minor bigint NOT NULL CHECK(amount_minor>0), currency text NOT NULL, status text NOT NULL CHECK(status IN ('captured','refunded','disputed')), verified_at timestamptz NOT NULL, captured_at timestamptz NOT NULL);
CREATE TABLE exam.payment_verification_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES exam.payments, method text NOT NULL, outcome text NOT NULL, provider_status text NOT NULL, evidence_hash text NOT NULL, checked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exam.payment_webhook_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, provider_event_id text NOT NULL, payload_hash text NOT NULL, signature_valid boolean NOT NULL, processing_status text NOT NULL DEFAULT 'pending', received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,provider_event_id));
CREATE TABLE exam.user_subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES exam.users, plan_version_id uuid NOT NULL REFERENCES exam.subscription_plan_versions, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','cancelled','revoked')), provider_subscription_id text UNIQUE, cancel_at_period_end boolean NOT NULL DEFAULT false, UNIQUE(user_id,plan_version_id));
CREATE TABLE exam.subscription_periods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subscription_id uuid NOT NULL REFERENCES exam.user_subscriptions, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, payment_id uuid NOT NULL UNIQUE REFERENCES exam.payments, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','revoked')), CHECK(ends_at-starts_at=interval '720 hours'));
CREATE TABLE exam.user_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES exam.users, test_version_id uuid NOT NULL REFERENCES exam.test_versions, status text NOT NULL DEFAULT 'in_progress' CHECK(status IN ('in_progress','submitted','scored','voided')), start_request_key uuid NOT NULL, started_at timestamptz NOT NULL, deadline_at timestamptz NOT NULL, submitted_at timestamptz, submission_reason text, rules_snapshot jsonb NOT NULL, UNIQUE(user_id,start_request_key), UNIQUE(id,test_version_id), CHECK(deadline_at>started_at));
CREATE TABLE exam.attempt_sections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL, test_version_id uuid NOT NULL, test_section_id uuid NOT NULL, started_at timestamptz, deadline_at timestamptz, status text NOT NULL DEFAULT 'pending', FOREIGN KEY(attempt_id,test_version_id) REFERENCES exam.user_attempts(id,test_version_id), FOREIGN KEY(test_section_id,test_version_id) REFERENCES exam.test_sections(id,test_version_id), UNIQUE(id,attempt_id), UNIQUE(attempt_id,test_section_id));
CREATE TABLE exam.attempt_questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL REFERENCES exam.user_attempts, attempt_section_id uuid NOT NULL, question_version_id uuid NOT NULL REFERENCES exam.question_versions, position integer NOT NULL, option_order jsonb NOT NULL DEFAULT '[]', scoring_snapshot jsonb NOT NULL, topic_snapshot jsonb NOT NULL DEFAULT '[]', FOREIGN KEY(attempt_section_id,attempt_id) REFERENCES exam.attempt_sections(id,attempt_id), UNIQUE(attempt_id,position), UNIQUE(attempt_id,question_version_id));
CREATE TABLE exam.attempt_answers(attempt_question_id uuid PRIMARY KEY REFERENCES exam.attempt_questions, response jsonb, marked_for_review boolean NOT NULL DEFAULT false, revision integer NOT NULL DEFAULT 1 CHECK(revision>0), saved_at timestamptz NOT NULL DEFAULT now(), reported_time_ms bigint CHECK(reported_time_ms>=0));
CREATE TABLE exam.attempt_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL REFERENCES exam.user_attempts, event_type text NOT NULL, request_key uuid, metadata jsonb NOT NULL DEFAULT '{}', occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exam.free_attempt_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES exam.users, attempt_id uuid NOT NULL REFERENCES exam.user_attempts, event_type text NOT NULL CHECK(event_type IN ('consume','restore')), delta_used integer NOT NULL, reverses_event_id uuid UNIQUE REFERENCES exam.free_attempt_events, reason text, actor_id uuid REFERENCES exam.users, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(attempt_id,event_type), CHECK((event_type='consume' AND delta_used=1 AND reverses_event_id IS NULL) OR (event_type='restore' AND delta_used=-1 AND reverses_event_id IS NOT NULL AND length(trim(reason))>0 AND actor_id IS NOT NULL)));
CREATE TABLE exam.attempt_authorizations(attempt_id uuid PRIMARY KEY REFERENCES exam.user_attempts, authorization_type text NOT NULL CHECK(authorization_type IN ('free','subscription')), subscription_period_id uuid REFERENCES exam.subscription_periods, free_event_id uuid UNIQUE REFERENCES exam.free_attempt_events, policy_snapshot jsonb NOT NULL, CHECK((authorization_type='free' AND free_event_id IS NOT NULL AND subscription_period_id IS NULL) OR (authorization_type='subscription' AND subscription_period_id IS NOT NULL AND free_event_id IS NULL)));
CREATE TABLE exam.attempt_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attempt_id uuid NOT NULL REFERENCES exam.user_attempts, grading_version integer NOT NULL CHECK(grading_version>0), score numeric NOT NULL, maximum_score numeric NOT NULL, correct_count integer NOT NULL, wrong_count integer NOT NULL, unanswered_count integer NOT NULL, scored_at timestamptz NOT NULL DEFAULT now(), supersedes_result_id uuid REFERENCES exam.attempt_results, UNIQUE(attempt_id,grading_version));
CREATE TABLE exam.answer_evaluations(result_id uuid REFERENCES exam.attempt_results, attempt_question_id uuid REFERENCES exam.attempt_questions, outcome text NOT NULL, awarded_marks numeric NOT NULL, grading_key_reference jsonb NOT NULL, PRIMARY KEY(result_id,attempt_question_id));
CREATE TABLE exam.result_section_summaries(result_id uuid REFERENCES exam.attempt_results, attempt_section_id uuid REFERENCES exam.attempt_sections, score numeric NOT NULL, counts jsonb NOT NULL, PRIMARY KEY(result_id,attempt_section_id));
CREATE TABLE exam.user_topic_performance(user_id uuid REFERENCES exam.users, topic_id uuid REFERENCES exam.topics, aggregates jsonb NOT NULL, calculation_version integer NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,topic_id));
CREATE TABLE exam.user_exam_performance(user_id uuid REFERENCES exam.users, exam_stage_id uuid REFERENCES exam.exam_stages, aggregates jsonb NOT NULL, calculation_version integer NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,exam_stage_id));
CREATE TABLE exam.question_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES exam.users, question_version_id uuid NOT NULL REFERENCES exam.question_versions, attempt_id uuid REFERENCES exam.user_attempts, reason text NOT NULL, status text NOT NULL DEFAULT 'open', resolution text);
CREATE TABLE exam.refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES exam.payments, provider_refund_id text NOT NULL UNIQUE, amount_minor bigint NOT NULL CHECK(amount_minor>0), status text NOT NULL, reason text NOT NULL);
CREATE TABLE exam.payment_disputes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES exam.payments, provider_dispute_id text NOT NULL UNIQUE, status text NOT NULL, amount_minor bigint NOT NULL CHECK(amount_minor>0));
CREATE TABLE exam.admin_audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL REFERENCES exam.users, action text NOT NULL, entity_type text NOT NULL, entity_id uuid NOT NULL, before_value jsonb, after_value jsonb, reason text NOT NULL, request_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exam.outbox_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL, aggregate_id uuid NOT NULL, payload jsonb NOT NULL, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exam.background_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), deduplication_key text NOT NULL UNIQUE, job_type text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', attempt_count integer NOT NULL DEFAULT 0, run_after timestamptz NOT NULL DEFAULT now(), last_error text);
CREATE TABLE exam.idempotency_requests(scope text, operation text, request_key uuid, request_hash text NOT NULL, resource_id uuid, status text NOT NULL, PRIMARY KEY(scope,operation,request_key));
CREATE INDEX ON exam.user_attempts(user_id,started_at DESC);
CREATE INDEX ON exam.subscription_periods(subscription_id,ends_at);
CREATE INDEX ON exam.question_topic_mappings(topic_id);
CREATE INDEX ON exam.background_jobs(run_after) WHERE status='pending';
CREATE INDEX ON exam.payment_webhook_events(received_at) WHERE processing_status='pending';
CREATE INDEX ON exam.free_attempt_events(user_id);
INSERT INTO exam.exam_families(code,name) VALUES ('ssc','SSC'),('rrb','Railway/RRB'),('banking','Banking'),('upsc','UPSC'),('defence','Defence'),('other','Other Government Exams');
INSERT INTO exam.permissions(code) VALUES ('attempt.restore');
INSERT INTO exam.roles(code) VALUES ('support_admin');
INSERT INTO exam.role_permissions SELECT r.id,p.id FROM exam.roles r CROSS JOIN exam.permissions p WHERE r.code='support_admin' AND p.code='attempt.restore';
COMMIT;
